// Demo 用輸入：換 host 測不同設備（prod-node-01 是 healthy，risk 應為 low）
return [{ json: {
  host: 'prod-node-03',
  question: '這台設備需要立即處理嗎？'
} }];

// 支援 Webhook（$json.body）與 Demo 路徑（$json 直接帶 host/question）
const b = $json.body || $json || {};
return [{ json: {
  host: b.host || 'prod-node-03',
  question: b.question || '這台設備需要立即處理嗎？'
} }];

// Merge(append) 只負責「等三個分支都完成」；取值用 $('節點名') 指名拿，不怕欄位衝突
const input = $('整理輸入').first().json;
const device = $('來源1: 即時狀態').first().json;
const history = $('來源2: 告警歷史').first().json;
const metrics = $('來源3: Metrics 趨勢').first().json;

const trend = (metrics.points || [])
  .map(p => `  ${p.timestamp.slice(11, 16)} CPU ${p.cpu}% / MEM ${p.memory}%`)
  .join('\n');
const alertLines = (history.alerts || [])
  .map(a => `  ${a.timestamp.slice(0, 16)} [${a.severity}] ${a.alertname}: ${a.message}`)
  .join('\n') || '  （24 小時內無告警記錄）';

const context = [
  `【即時狀態】host: ${device.host}，status: ${device.status}，CPU ${device.cpu}%，Memory ${device.memory}%，Disk ${device.disk}%，uptime ${device.uptime}`,
  '',
  `【歷史告警】過去 24 小時共 ${history.count} 條：`,
  alertLines,
  '',
  '【Metrics 趨勢】過去 6 小時：',
  trend
].join('\n');
return [{ json: { host: input.host, question: input.question, context } }];

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const clean = text.replace(/```json\n?|```/g, '').trim();
let parsed = {};
try { parsed = JSON.parse(clean); }
catch (e) { parsed = { assessment: text, risk_level: 'unknown' }; }
const src = $('組合三源上下文').item.json;
return [{ json: {
  host: src.host,
  question: src.question,
  assessment: parsed.assessment || '',
  matched_runbook: parsed.matched_runbook || null,
  recommendation: parsed.recommendation || '',
  risk_level: parsed.risk_level || 'unknown'
} }];
